#!/usr/bin/env python3
"""Dependency-free macOS JavaScriptCore checks plus static asset checks.

These exercise the data/rendering/interaction functions without replacing
browser QA. Run with: python3 tests/validate.py
"""
import ctypes
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
lib = ctypes.CDLL('/System/Library/Frameworks/JavaScriptCore.framework/JavaScriptCore')
PTR = ctypes.c_void_p
lib.JSGlobalContextCreate.argtypes = [PTR]
lib.JSGlobalContextCreate.restype = PTR
lib.JSStringCreateWithUTF8CString.argtypes = [ctypes.c_char_p]
lib.JSStringCreateWithUTF8CString.restype = PTR
lib.JSEvaluateScript.argtypes = [PTR, PTR, PTR, PTR, ctypes.c_int, ctypes.POINTER(PTR)]
lib.JSEvaluateScript.restype = PTR
lib.JSValueToStringCopy.argtypes = [PTR, PTR, ctypes.POINTER(PTR)]
lib.JSValueToStringCopy.restype = PTR
lib.JSStringGetMaximumUTF8CStringSize.argtypes = [PTR]
lib.JSStringGetMaximumUTF8CStringSize.restype = ctypes.c_size_t
lib.JSStringGetUTF8CString.argtypes = [PTR, ctypes.c_char_p, ctypes.c_size_t]
lib.JSStringGetUTF8CString.restype = ctypes.c_size_t

PRELUDE = r'''
const structuredClone = x => JSON.parse(JSON.stringify(x));
const localStorage = {getItem(){return null;},setItem(){}};
const location = {hash:''};
const history = {length:1,back(){}};
const window = {addEventListener(){},scrollTo(){}};
const setTimeout=()=>1,clearTimeout=()=>{};
const fakeNode = () => ({innerHTML:'',textContent:'',open:false,
 classList:{add(){},remove(){}},scrollIntoView(){},focus(){},
 showModal(){this.open=true;},close(){this.open=false;},addEventListener(){}});
const elements = new Map();
const document = {title:'',addEventListener(){},querySelector(s){if(!elements.has(s))elements.set(s,fakeNode());return elements.get(s);}};
class URLSearchParams {constructor(s){this.p=new Map(String(s||'').split('&').filter(Boolean).map(v=>{const a=v.split('=');return [decodeURIComponent(a[0]),decodeURIComponent(a[1]||'')];}));}get(k){return this.p.get(k)||null;}}
class FormData {constructor(f){this.p=f.values||{};}get(k){const v=this.p[k];return Array.isArray(v)?v[0]:v||null;}getAll(k){const v=this.p[k];return v===undefined?[]:Array.isArray(v)?v:[v];}has(k){return k in this.p;}}
'''
TESTS = r'''
const results=[];
function assert(value,message){if(!value)throw new Error(message);}
function test(name,fn){try{fn();results.push({name,ok:true});}catch(e){results.push({name,ok:false,error:String(e)});}}
function resetTest(){state=structuredClone(INITIAL);location.hash='';currentRoute='seasons';activeFilter='全部';}
function submitTest(kind,values,intent){const error=fakeNode();const f={dataset:{form:kind},values,checkValidity:()=>true,reportValidity(){},querySelector:()=>error};f.closest=()=>f;handleSubmit({target:f,submitter:{value:intent},preventDefault(){}});return error.textContent;}
for(const route of ROUTES){test('render '+route[0],()=>{resetTest();state.role=route[2]==='public'?'visitor':route[2];currentRoute=route[0];location.hash='#'+route[0];const html=PAGES[route[0]]();assert(typeof html==='string'&&html.includes('id="main"'),'No main view');assert(!html.includes('NaN'),'Invalid numerical output');});}
test('one handler per IA route',()=>assert(ROUTES.length===48&&ROUTES.every(r=>typeof PAGES[r[0]]==='function'),'Missing IA route'));
test('initial score conservation',()=>{resetTest();assert(allProjects().reduce((s,p)=>s+projectScore(p),0)===used(),'Project scores differ from ledger');});
test('registration closed blocks submit',()=>{resetTest();const err=submitTest('apply',{name:'Test',wechat:'test',skills:'test',direction:'test',time:'test'});assert(err&&state.application===null,'Closed registration accepted');});
test('registration and approval status are separate',()=>{resetTest();state.role='participant';state.registration='open';const err=submitTest('apply',{name:'Test',wechat:'test',skills:'test',direction:'test',time:'test'});assert(!err&&state.application.status==='审核中'&&state.role==='participant','Application failed');assert(canWrite('project'),'Unapproved applicant can create project');});
test('approved participant creates one project',()=>{resetTest();state.role='participant';state.application={id:'t',name:'Test',status:'已通过'};state.applications.push(state.application);const err=submitTest('create-project',{name:'Test project',members:'Test',description:'a real project',challenges:['c1'],source:'new'});assert(!err&&state.ownProject&&projectScore(state.ownProject)===0,'Create project failed');assert(submitTest('create-project',{name:'again',members:'Test',challenges:['c1']}),'Duplicate project allowed');});
test('full challenge blocks project creation',()=>{resetTest();state.role='participant';state.application={name:'Test',status:'已通过'};state.applications.push(state.application);assert(submitTest('create-project',{name:'Test',members:'Test',challenges:['c3']}),'Capacity not enforced');});
test('score updates ledger and balance once',()=>{resetTest();state.role='judge';const before=used(),err=submitTest('score',{workId:'w1',points:'150',reason:'这是一条具有充分证据且可以解释的有效评分理由。'});assert(!err&&used()===before+150,'Score not accounted');assert(judge().allocated-judgeUsed(actor)===1050,'Balance mismatch');assert(submitTest('score',{workId:'w1',points:'150',reason:'这是一条具有充分证据且可以解释的有效评分理由。'}),'Duplicate review accepted');assert(used()===before+150,'Duplicate changed score');});
test('score cap blocks oversized score',()=>{resetTest();state.role='judge';assert(submitTest('score',{workId:'w1',points:'201',reason:'这是一条具有充分证据且可以解释的有效评分理由。'}),'Cap not enforced');assert(used()===350,'Rejected score changed ledger');});
test('self-scoring blocked',()=>{resetTest();state.role='judge';state.ownProject={id:'p1'};assert(scoreBlock(workBy('w1')),'Self-score allowed');});
test('scope blocks unrelated projects',()=>{resetTest();state.role='judge';judge().scope='c2';assert(scoreBlock(workBy('w1')),'Scope ignored');});
test('budget blocks additional commitments',()=>{resetTest();state.role='judge';state.season.budget=used();assert(submitTest('score',{workId:'w1',points:'100',reason:'这是一条具有充分证据且可以解释的有效评分理由。'}),'Budget ignored');});
test('works close before scoring closes',()=>{resetTest();state.role='judge';state.phase='workClosed';assert(!canWrite('score'),'Scoring blocked too early');state.role='participant';state.ownProject={id:'x'};assert(canWrite('work'),'Work publishing allowed after deadline');});
test('pause and cancellation block writes',()=>{for(const p of ['suspended','cancelled']){resetTest();state.phase=p;state.registration='open';assert(canWrite('apply'),'Application accepted during '+p);state.role='judge';assert(canWrite('score'),'Scoring accepted during '+p);}});
test('large score requires second review',()=>{resetTest();state.role='judge';submitTest('score',{workId:'w1',points:'190',reason:'这是一条具有充分证据且可以解释的有效评分理由。'});assert(!state.ledger.at(-1).reviewed,'Large score did not require review');});
test('reviewer cannot review own score',()=>{resetTest();state.role='organizer';state.ledger[0].reviewed=false;state.ledger[0].judgeId='organizer-demo';assert(submitTest('review-score',{id:'l1',decision:'approve',reason:'测试复核说明'}),'Self-review allowed');assert(!state.ledger[0].reviewed,'Self-review mutated record');});
test('admin reversal preserves record and recalculates',()=>{resetTest();state.role='admin';const count=state.ledger.length;const err=submitTest('reverse',{id:'l1',reason:'测试发现证据不完整需要冲正评分',terms:'on'});assert(!err&&state.ledger.length===count&&state.ledger[0].reversed,'Record was deleted or reversal failed');assert(used()===210&&workScore(workBy('w1'))===0,'Scores not recalculated');assert(submitTest('reverse',{id:'l1',reason:'不能重复冲正的测试原因',terms:'on'}),'Double reversal allowed');});
test('organizer cannot execute ordinary reversal',()=>{resetTest();state.role='organizer';assert(submitTest('reverse',{id:'l1',reason:'这里是一条测试用的冲正原因'}),'Permission ignored');assert(!state.ledger[0].reversed,'Unauthorized reversal changed state');});
test('only unused allocation can be reclaimed',()=>{resetTest();state.role='organizer';assert(submitTest('reclaim',{id:'judge-lin',amount:'1000'}),'Used allocation reclaimed');assert(state.judges[0].allocated===1000,'Invalid reclaim mutated allocation');assert(!submitTest('reclaim',{id:'judge-lin',amount:'100'}),'Valid reclaim rejected');assert(state.judges[0].allocated===900,'Reclaim failed');});
test('private work hidden from enterprise and visitor',()=>{resetTest();const w={...state.works[0],visibility:'verification'};state.role='visitor';assert(!canViewWork(w),'Visitor saw private material');state.role='enterprise';assert(!canViewWork(w),'Enterprise saw private material');state.role='admin';assert(canViewWork(w),'Admin cannot see evidence');});
test('unapproved season does not expose detail',()=>{resetTest();state.season.approved=false;assert(seasonPage().includes('尚未公开'),'Unapproved season exposed');});
test('HTML values are escaped',()=>assert(esc('<img onerror="bad">').includes('&lt;img'),'Unescaped user text'));

const organizerSections={organizer:['赛季选择','参与和产出','预算使用情况','待处理事项'],'season-config':['基本信息','主办与发奖信息','赛程设置','参赛与评分规则','公开规则卡','发布操作'],'publish-check':['必备条件清单','缺失项处理','平台审批进度'],'season-manage':['赛季状态','赛程调整','开赛与暂停','取消赛季'],applications:['报名审核','微信邀请记录','选手与组队','调整申请'],'challenge-manage':['命题管理','参考资料','已发布','已关闭','已归档'],points:['赛季可评积分','评委名单与权限','评委积分分配','额度与停用'],review:['里程碑审核','大额评分复核','商业结果核验','异议与处理记录'],budget:['奖励预算','结算前检查','奖金核定','发放与最终结果'],announcements:['公告内容','通知对象','未读提醒']};
for(const [route,sections] of Object.entries(organizerSections)){test('organizer IA sections '+route,()=>{resetTest();state.role='organizer';currentRoute=route;const html=PAGES[route]();for(const title of sections)assert(html.includes(title),'Missing '+title);});}
test('copy season preserves original and clears business records',()=>{resetTest();state.role='organizer';copyOrganizerSeason();const copied=state.season.code;assert(copied!=='S01'&&state.season.budget===0&&state.season.pool===0,'Budget or identity copied');assert(state.works.length===0&&state.ledger.length===0&&state.judges.length===0&&state.applications.length===0,'Business records copied');assert(allProjects().length===0,'Copied draft contains original projects');switchOrganizerSeason('S01');assert(state.season.code==='S01'&&state.works.length===3&&used()===350,'Original season not preserved');assert(state.organizerSeasonRecords[copied].season.draft,'Draft not retained for later switching');});
test('season initiation creates independent blank draft',()=>{resetTest();state.role='organizer';const err=submitTest('season-create',{name:'全新赛季',seasonType:'hackathon',city:'上海'});assert(!err&&state.season.name==='全新赛季'&&state.season.type==='hackathon','Creation failed');assert(state.season.draft&&!state.season.approved&&state.phase==='upcoming','Draft status incorrect');assert(state.season.dates.every(d=>d==='')&&state.works.length===0&&state.judges.length===0,'Inherited dates or records');const code=state.season.code;switchOrganizerSeason('S01');assert(state.works.length===3&&used()===350,'Original changed');assert(organizerDraftsPage().includes('全新赛季'),'New draft missing');handleClick({target:{closest:()=>({dataset:{action:'edit-season-draft',id:code}})}});assert(state.season.code===code&&location.hash==='season-config','Draft does not open configuration');});
test('organizer global navigation precedes season configuration',()=>{resetTest();state.role='organizer';currentRoute='organizer';const html=organizerPage();const labels=['全部赛季','赛季发起','草稿','sidebar-divider','sidebar-season-label','赛季工作台','赛季配置'];for(let i=1;i<labels.length;i++)assert(html.indexOf(labels[i-1])<html.indexOf(labels[i]),'Incorrect navigation order: '+labels[i]);assert(!html.includes('赛季发起与配置'),'Combined entry remains');});
test('draft list excludes submitted and active seasons',()=>{resetTest();state.role='organizer';currentRoute='organizer-drafts';const html=organizerDraftsPage().split('<main')[1];assert(html.includes('灵感发芽季')&&!html.includes('社区共创季')&&!html.includes('产品生长季'),'Draft filtering failed');});
function validSeasonConfig(){return {name:'更新后的赛季',code:state.season.code,organizer:'测试主办方',payer:'测试发奖方',theme:'赛季介绍',themeName:'赛季主题',reviewer:'yes',budget:'12000',ratio:'1',cap:'200',threshold:'180',...Object.fromEntries(state.season.dates.map((date,i)=>['date'+i,date]))};}
test('configuration saves latest edits before review submission',()=>{resetTest();state.role='organizer';state.phase='upcoming';state.season.draft=true;state.season.approved=false;const err=submitTest('season-config',validSeasonConfig(),'publish');assert(!err&&state.season.name==='更新后的赛季','Edits not saved');assert(!state.season.draft&&!state.season.approved,'Review was not submitted');assert(seasonPublishButton(true).includes('审核中')&&seasonPublishButton(true).includes('disabled'),'Pending action not disabled');let rejected=false;try{submitSeasonForReview();}catch(e){rejected=true;}assert(rejected,'Duplicate review accepted');});
test('failed publish check retains saved configuration as draft',()=>{resetTest();state.role='organizer';state.phase='upcoming';state.season.draft=true;state.season.approved=false;state.season.pool=0;const err=submitTest('season-config',validSeasonConfig(),'publish');assert(err.includes('积分池总量大于零'),'Missing item not explained');assert(state.season.draft&&state.season.name==='更新后的赛季','Draft or edits lost');});
test('ordinary save does not submit and admin publish becomes approved',()=>{resetTest();state.role='organizer';state.phase='upcoming';state.season.draft=true;state.season.approved=false;assert(!submitTest('season-config',validSeasonConfig())&&state.season.draft,'Ordinary save submitted');state.role='admin';assert(!submitTest('season-config',validSeasonConfig(),'publish')&&state.season.approved&&!state.season.draft,'Admin publish failed');assert(seasonPublishButton(true).includes('已发布'),'Published label missing');});
function challengeValues(id='new'){return {id,name:'测试命题',company:'测试企业',type:'商单验证',description:'问题',resource:'资源',target:'成果',evidence:'证据',verifier:'核验人',reward:'评分奖励',rights:'授权范围',capacity:'6'};}
test('challenge list nests editing in single challenge',()=>{resetTest();state.role='organizer';currentRoute='challenge-manage';const html=challengeManagePage().split('<main')[1];assert(html.includes('#challenge-edit?id=c1')&&!html.includes('需求与资源编辑')&&!html.includes('证据与权益编辑')&&!html.includes('名额与冻结'),'Flat sections remain');location.hash='#challenge-edit?id=c1';const detail=challengeEditPage();assert(detail.includes('问题与资源')&&detail.includes('证据与评分')&&detail.includes('版本记录'),'Detail incomplete');});
test('challenge draft becomes reference then published with required checks',()=>{resetTest();state.role='organizer';state.phase='upcoming';const values=challengeValues();assert(!submitTest('challenge-edit',values),'Save failed');const id=state.lastEditedChallengeId;assert(!publicChallenges().some(c=>c.id===id),'Draft exposed');values.id=id;values.evidence='';assert(submitTest('challenge-edit',values,'publish').includes('证据门槛'),'Incomplete publish accepted');assert(!submitTest('challenge-edit',values,'reference'),'Reference failed');assert(publicChallenges().some(c=>c.id===id)&&!selectableChallenges().some(c=>c.id===id),'Reference selectable');values.evidence='完整证据';assert(!submitTest('challenge-edit',values,'publish'),'Publish failed');assert(selectableChallenges().some(c=>c.id===id),'Published challenge missing');location.hash='#challenge?id='+id;assert(challengePage().includes('测试命题'),'Published detail missing');});
test('published challenge revisions retain previous terms',()=>{resetTest();state.role='organizer';const old=organizerChallenges().find(c=>c.id==='c1');const values={...old,id:'c1',rights:'更新的授权条款',capacity:'6'};assert(!submitTest('challenge-edit',values),'Revision failed');const item=organizerChallenges().find(c=>c.id==='c1');assert(item.version===2&&item.versions[0].rights===old.rights&&item.versions[0].description===old.description,'Old version overwritten');assert(!submitTest('challenge-edit',values)&&organizerChallenges().find(c=>c.id==='c1').version===2,'Unchanged save creates revision');location.hash='#challenge-edit?id=c1&tab=versions';assert(challengeEditPage().includes(old.description),'History not readable');});
test('freeze prevents challenge creation publication and closure',()=>{resetTest();state.role='organizer';assert(submitTest('challenge-edit',challengeValues(),'publish'),'Frozen creation allowed');const before=organizerChallenges();handleClick({target:{closest:()=>({dataset:{action:'confirm-close-challenge:c1'}})}});assert(organizerChallenges().find(c=>c.id==='c1').status==='已发布','Frozen closure allowed');state.phase='upcoming';assert(!submitTest('challenge-edit',challengeValues()),'Draft save failed');const id=state.lastEditedChallengeId;state.phase='active';assert(submitTest('challenge-edit',{...challengeValues(id)},'publish'),'Frozen publication allowed');});
test('closed challenge retains history and cannot be selected',()=>{resetTest();state.role='organizer';state.phase='upcoming';handleClick({target:{closest:()=>({dataset:{action:'confirm-close-challenge:c1'}})}});assert(organizerChallenges().find(c=>c.id==='c1').status==='已关闭'&&publicChallenges().some(c=>c.id==='c1'),'Closed history lost');assert(!selectableChallenges().some(c=>c.id==='c1'),'Closed challenge selectable');state.phase='active';state.role='participant';state.application={name:'Test',status:'已通过'};state.applications.push(state.application);assert(submitTest('create-project',{name:'Test',members:'Test',challenges:['c1']}),'Closed selection accepted');});
test('challenge capacity cannot drop below selected count and copies start empty',()=>{resetTest();state.role='organizer';assert(submitTest('challenge-edit',{...challengeValues('c1'),capacity:'2'}),'Invalid capacity accepted');state.phase='upcoming';assert(!submitTest('challenge-edit',challengeValues(),'publish'),'Publish failed');copyOrganizerSeason();assert(organizerChallenges().length===0,'Copied challenge records');switchOrganizerSeason('S01');assert(organizerChallenges().some(c=>c.name==='测试命题'),'Original records lost');});
test('enterprise navigation contains only primary areas and own challenges',()=>{resetTest();state.role='enterprise';currentRoute='enterprise';const html=enterprisePage();const sidebar=html.split('<aside')[1].split('</aside>')[0];assert(sidebar.includes('本企业命题')&&sidebar.includes('资源与交付')&&sidebar.includes('合作与出资'),'Primary navigation missing');assert(sidebar.includes('#challenge-draft')&&sidebar.includes('#enterprise-drafts')&&!sidebar.includes('#report'),'Creation, draft or progress navigation incorrect');assert(sidebar.indexOf('本企业命题')<sidebar.indexOf('创建新命题')&&sidebar.indexOf('创建新命题')<sidebar.indexOf('命题草稿')&&sidebar.indexOf('命题草稿')<sidebar.indexOf('sidebar-divider')&&sidebar.indexOf('sidebar-divider')<sidebar.indexOf('资源与交付'),'Enterprise navigation order');assert(!html.includes('把创作者的一次合作')&&html.includes('5,000'),'Foreign challenge or funding error');location.hash='#enterprise-challenge?id=c2';assert(enterpriseChallengePage().includes('命题不存在'),'Foreign enterprise detail exposed');});
test('enterprise hands draft to managers and cannot publish or edit directly',()=>{resetTest();state.role='enterprise';state.phase='upcoming';assert(!submitTest('challenge-draft',{name:'企业新草稿',type:'商单验证',customer:'客户',description:'真实问题',resources:'企业资源',evidence:'验收记录',rights:'企业条款',company:'冒用企业'}),'Draft submit failed');const draft=state.draftChallenges[0];assert(draft.company===ENTERPRISE_COMPANY&&!draft.published,'Forged identity or publication');assert(!publicChallenges().some(c=>c.id===draft.id),'Draft publicly exposed');location.hash='#enterprise-challenge?id='+draft.id;const detail=enterpriseChallengePage();assert(detail.includes('企业新草稿')&&!detail.includes('发布命题')&&!detail.includes('data-form="challenge-edit"'),'Enterprise editing formal challenge');assert(submitTest('challenge-edit',challengeValues(draft.id),'publish'),'Enterprise published');state.role='organizer';assert(organizerChallenges().some(c=>c.id===draft.id),'Organizer cannot see enterprise submission');const values={...challengeValues(draft.id),company:ENTERPRISE_COMPANY,name:'主办方完善命题'};assert(!submitTest('challenge-edit',values,'publish'),'Organizer cannot publish');state.role='admin';values.name='管理员修订命题';assert(!submitTest('challenge-edit',values),'Admin cannot modify');state.role='enterprise';location.hash='#enterprise-challenge?id='+draft.id;assert(enterpriseChallengePage().includes('管理员修订命题')&&enterpriseChallengePage().includes('已发布'),'Enterprise missing published status');});
test('administrator can navigate to shared manager editor and enterprise cannot',()=>{resetTest();state.role='admin';location.hash='#challenge-edit?id=c1';render();assert(elements.get('#app').innerHTML.includes('data-form="challenge-edit"'),'Admin editor route blocked');assert(elements.get('#app').innerHTML.includes('平台管理员导航'),'Wrong admin navigation');state.role='enterprise';render();assert(elements.get('#app').innerHTML.includes('这个页面需要对应身份'),'Enterprise accessed manager route');});
test('published progress is available to every role with only public tagged works',()=>{resetTest();state.works[0].tag='c1';state.works.push({...state.works[0],id:'private',title:'私密工作记录',visibility:'verification'});for(const role of Object.keys(ROLES)){state.role=role;location.hash='#challenge-progress?id=c1';const html=challengeProgressPage();assert(html.includes('园区算力拼车')&&html.includes(state.works[0].title),'Progress unavailable to '+role);assert(!html.includes('私密工作记录')&&!html.includes('合作便利店'),'Private or unrelated work exposed');}state.season.approved=false;state.role='visitor';assert(challengeProgressPage().includes('尚未公开'),'Unapproved season exposed');});
test('enterprise resource and contribution actions remain scoped',()=>{resetTest();state.role='enterprise';assert(resourcesPage().includes('测试算力')&&resourcesPage().includes('记录验收'),'Resource controls missing');assert(partnershipPage().includes('¥5,000')&&partnershipPage().includes('提交推荐'),'Funding or recommendations missing');assert(!submitTest('resource',{index:'0',status:'已使用'})&&state.resources[0]==='已使用','Resource update failed');assert(submitTest('accept-delivery',{id:'p2',feedback:'不属于本企业'}),'Foreign project acceptance allowed');assert(!submitTest('accept-delivery',{id:'p1',feedback:'已验收'}),'Own delivery blocked');});
test('project progress uses that project milestones and hides private results',()=>{resetTest();state.role='visitor';location.hash='#project?id=p1';state.milestones=[{projectId:'p2',step:1,status:'另一项目状态'}];state.results=[{projectId:'p1',title:'私密成果记录',visibility:'verification',status:'已核验',level:'R3'}];const html=projectPage();assert(!html.includes('另一项目状态')&&!html.includes('私密成果记录'),'Other project or private results exposed');assert(!html.includes('href="#milestone?step='),'Visitor sees submission entry');});
test('enterprise unsent drafts stay private and move to pending on submission',()=>{resetTest();state.role='enterprise';state.phase='upcoming';assert(!submitTest('challenge-draft',{name:'尚未提交'},'save-draft'),'Partial draft rejected');const id=state.enterpriseChallengeDrafts[0].id;currentRoute='enterprise-drafts';assert(enterpriseDraftsPage().includes('尚未提交'),'Saved draft missing');assert(!organizerChallenges().some(c=>c.id===id)&&!enterpriseChallenges().some(c=>c.id===id),'Unsubmitted draft handed to organizer');location.hash='#challenge-draft?id='+id;assert(challengeDraftPage().includes('尚未提交'),'Draft cannot reopen');assert(!submitTest('challenge-draft',{id,name:'草稿第二版'},'save-draft')&&state.enterpriseChallengeDrafts.length===1,'Save duplicated draft');assert(submitTest('challenge-draft',{id,name:'草稿第二版'},'submit'),'Incomplete submission accepted');assert(state.enterpriseChallengeDrafts.length===1,'Invalid submission lost draft');assert(!submitTest('challenge-draft',{id,name:'已交主办方',description:'真实问题'},'submit'),'Submission failed');assert(state.enterpriseChallengeDrafts.length===0&&!enterpriseDraftsPage().includes('已交主办方'),'Submitted item remains among unsent drafts');activeFilter='待发布';assert(enterprisePage().includes('已交主办方'),'Pending submission missing');location.hash='#enterprise-challenge?id='+id;assert(enterpriseChallengePage().includes('待发布'),'Detail uses draft label');assert(organizerChallenges().some(c=>c.id===id),'Organizer cannot see submitted item');assert(submitTest('challenge-draft',{id,name:'重复提交',description:'问题'},'submit'),'Submitted item editable by enterprise');});
test('all enterprise pages omit global phase notices',()=>{resetTest();state.role='enterprise';for(const phase of ['cancelled','suspended','settling','ended','archived']){state.phase=phase;for(const route of ROUTES.filter(r=>r[2]==='enterprise')){currentRoute=route[0];location.hash='#'+route[0]+(['enterprise-challenge','report'].includes(route[0])?'?id=c1':'');const html=PAGES[route[0]]();assert(!html.includes(phaseNotice()),'Enterprise phase notice remains: '+route[0]+' '+phase);}}state.role='organizer';currentRoute='organizer';assert(organizerPage().includes(phaseNotice()),'Organizer notice removed');});
test('enterprise list identifies publication activity and new publications retain context',()=>{resetTest();state.role='enterprise';assert(enterprisePage().includes('发布活动')&&enterprisePage().includes(state.season.name),'Existing publication activity missing');state.role='organizer';state.phase='upcoming';state.season.name='城市共创黑客松';state.season.type='hackathon';assert(!submitTest('challenge-edit',{...challengeValues(),company:ENTERPRISE_COMPANY},'publish'),'Publish failed');const id=state.lastEditedChallengeId;const published=organizerChallenges().find(c=>c.id===id);assert(published.publishedActivity.name==='城市共创黑客松'&&published.publishedActivity.type==='hackathon','Publication context missing');state.season.name='修改后的活动名';state.role='enterprise';assert(enterprisePage().includes('城市共创黑客松'),'Publication label not retained');location.hash='#enterprise-challenge?id='+id;assert(enterpriseChallengePage().includes('城市共创黑客松'),'Detail missing activity');assert(challengePublishedActivity({status:'草稿'})===null,'Pending item shown as published');});
test('upcoming banner explores correct event details with timeline and rules',()=>{resetTest();state.role='participant';for(const code of ['S02']){state.bannerCode=code;const home=seasonsPage();assert(!home.includes('data-action="featured-event:S02"'),'Removed seed remains in banner');location.hash='#season?code='+code;const before=JSON.stringify(state);const html=seasonPage();assert(html.includes(UPCOMING_EVENTS[code].name)&&html.includes('完整赛程时间轴')&&html.includes('赛季规则'),'Upcoming detail incomplete');for(const date of UPCOMING_EVENTS[code].registrationDates)assert(html.includes(date),'Registration dates missing');assert(html.includes('报名 '+guestFormatDay(UPCOMING_EVENTS[code].registrationDates[0])+' 开放')&&!html.includes(':apply'),'Registration enabled');assert(!html.includes('园区算力拼车')&&!html.includes('已评积分'),'Current activity data leaked');assert(JSON.stringify(state)===before,'Browsing changes selected season');}state.season.approved=false;assert(seasonPage().includes('完整赛程时间轴'),'Upcoming visibility depends on unrelated selected season');});
test('upcoming activity application remains blocked even if current season is open',()=>{resetTest();state.registration='open';for(const code of ['S02']){location.hash='#apply?code='+code;assert(!applyPage().includes('data-form="apply"'),'Upcoming registration form exposed');assert(submitTest('apply',{name:'Test',wechat:'test',skills:'test',direction:'test',time:'test'}),'Upcoming application accepted');assert(state.application===null,'Upcoming application created');}});
test('featured activities match cards and detail status',()=>{resetTest();assert(featuredEvents().map(e=>e.code).join(',')==='S01,W01,H02','Wrong featured activities');for(const event of featuredEvents()){const card=homeEventTickets().find(c=>c.code===event.code);assert(card.status===event.status&&card.url===event.url&&card.date.includes(event.date),'Card/banner mismatch');location.hash=event.url;assert(seasonPage().includes(event.status)&&seasonPage().includes(event.name),'Detail mismatch');}assert(homeEventTickets().filter(c=>c.title==='种子季').length===0,'Duplicate seed activity');activeFilter='进行中';assert(eventTicketGrid().includes('城市黑客松'),'Hackathon missing from active cards');});
test('active hackathon detail and entry use independent activity data',()=>{resetTest();state.role='participant';location.hash='#season?code=H02';const before=JSON.stringify(state);const html=seasonPage();assert(html.includes('进行中')&&html.includes('完整赛程时间轴')&&html.includes('赛季规则')&&html.includes('邻里共享站')&&html.includes('共享站第一版原型'),'Hackathon detail incomplete');assert(JSON.stringify(state)===before,'Detail overwrites current season');enterPublicActivity('H02');assert(state.phase==='active'&&state.season.code==='H02'&&allProjects()[0].id==='hp1','Cannot enter active hackathon');assert(state.organizerSeasonRecords.S01.season.code==='S01','Original season lost');assert(featuredEvents().length===3&&featuredEvents()[0].name==='生长季','Banner changed with workspace');});
test('public activity entry keeps the selected activity through navigation',()=>{resetTest();state.role='participant';handleClick({target:{closest:()=>({dataset:{action:'enter-public-activity:H02:project?id=hp1'}})}});assert(state.season.code==='H02'&&location.hash==='project?id=hp1'&&projectPage().includes('邻里共享站'),'Project entry loses hackathon context');location.hash='#season?code=S01';assert(seasonPage().includes('data-action="enter-public-activity:S01:challenge?id=c1"'),'Original activity links lose context');state.role='organizer';copyOrganizerSeason();assert(allProjects().length===0&&organizerChallenges().length===0,'Copy inherited hackathon projects');});
test('homepage orders activity states and removes seed from both areas',()=>{resetTest();state.bannerCode='S02';const cards=homeEventTickets();for(let i=1;i<cards.length;i++)assert(activityOrder(cards[i-1])<=activityOrder(cards[i]),'Activity states out of order');assert(!seasonsPage().includes('种子季'),'Seed remains on homepage');activeFilter='报名中';const html=eventTicketGrid();assert(html.includes('共创工作坊')&&!html.includes('城市黑客松'),'Registration filter incorrect');state.phase='upcoming';state.registration='notOpen';assert(featuredEvents()[0].code==='S01'&&homeEventTickets()[0].code==='S01','Upcoming activities not first');});
test('registration workshop sits in middle and shares card details',()=>{resetTest();state.role='participant';const events=featuredEvents();assert(events[1].code==='W01'&&events[1].status==='报名中','Middle activity missing');assert(homeEventTickets().filter(c=>c.code==='W01').length===1,'Workshop duplicated');state.bannerCode='W01';assert(seasonsPage().includes('href="#season?code=W01" class="hero-cta"'),'Workshop explore link incorrect');location.hash='#season?code=W01';const html=seasonPage();assert(html.includes('报名中')&&html.includes('共创工作坊')&&html.includes('立即报名'),'Workshop details incorrect');enterPublicActivity('W01');location.hash='#apply';assert(applyPage().includes('data-form="apply"')&&!canWrite('apply'),'Workshop registration unavailable');});
test('entire activity cards link to matching season detail',()=>{resetTest();const html=eventTicketGrid();assert(!html.includes('<article class="event-ticket"'),'Card remains non-link');assert(!html.includes('<a class="event-ticket-cover"')&&!html.includes('<a class="event-ticket-button"'),'Nested links remain');for(const card of homeEventTickets()){assert(card.url.startsWith('#season?code='),'Card skips season detail');assert(html.includes('class="event-ticket-link" href="'+card.url+'"'),'Full card link missing');location.hash=card.url;assert(seasonPage().includes(card.title),'Wrong detail for '+card.code);}});
test('detail lifecycle keeps event and registration status separate',()=>{resetTest();state.role='visitor';state.detailStateVersion=1;for(const [phase,registration,status,cta] of [['upcoming','notOpen','即将开始','敬请期待'],['upcoming','open','报名中','立即报名'],['upcoming','closed','报名已截止','报名已截止'],['active','closed','进行中','报名已截止'],['archived','closed','已归档','查看赛季成果']]){state.phase=phase;state.registration=registration;const html=seasonDetailHeader();assert(html.includes(status)&&html.includes(cta),'Wrong lifecycle '+phase+' '+registration);assert(!html.includes('aria-label="已报名"'),'Unregistered visitor stamped enrolled');if(phase!=='upcoming'||registration!=='open')assert(!html.includes('>立即报名<'),'Registration allowed in wrong phase');}});
test('personal application states produce only the matching entry',()=>{resetTest();state.role='participant';state.phase='upcoming';state.registration='open';for(const [status,label] of [['审核中','查看报名状态'],['候补','查看候补状态'],['已通过','进入我的赛季'],['未通过','查看报名状态']]){state.application={id:'a',name:'Test',status};const html=seasonDetailHeader();assert(html.includes(status)&&html.includes(label),'Missing personal application state');assert(!html.includes('>立即报名<'),'Existing application can reapply');assert(html.includes('aria-label="已报名"')===(status!=='未通过'),'Wrong enrollment stamp');}state.phase='active';state.application.status='已通过';state.ownProject={id:'p1',name:'我的测试项目',challenges:['c1'],members:['Test']};assert(seasonDetailHeader().includes('查看下一里程碑'),'Approved project missing next milestone');state.phase='archived';assert(seasonDetailHeader().includes('我的赛季记录'),'Archived participation record missing');});
test('timeline progress follows registration and phase with chronological dates',()=>{resetTest();state.phase='upcoming';state.registration='notOpen';let html=seasonDetailTimeline();assert(!html.includes('aria-current="step"')&&!html.includes('timeline-item done'),'Future timeline shows completed milestones');state.registration='open';state.season.dates[0]='2026-01-01';html=seasonDetailTimeline();assert((html.match(/aria-current="step"/g)||[]).length===1,'Registration timeline not current');state.phase='archived';html=seasonDetailTimeline();assert(!html.includes('aria-current="step"'),'Archive has current stage');assert((html.match(/timeline-item done/g)||[]).length===8,'Archive timeline incomplete');});
test('shared detail uses guest sections and activity-specific data',()=>{resetTest();state.role='participant';location.hash='#season?code=S01';const html=seasonPage();for(const text of ['即将开始','报名 11月15日 开放','赛季规则','公告','奖励预算','积分归属','奖励核定','完整赛程时间轴','评委公示','1 积分 = 1 元'])assert(html.includes(text),'Shared content missing: '+text);assert(!html.includes('已评积分'),'Legacy internal metric remains');location.hash='#season?code=H02';const hack=seasonPage();for(const text of ['进行中','完整赛程时间轴','赛季规则','企业命题','Top 5','公开作品','邻里共享站','共享站第一版原型'])assert(hack.includes(text),'Hackathon content lost: '+text);location.hash='#season?code=P00';assert(seasonPage().includes('赛后成果')&&seasonPage().includes('13 个项目'),'Archived content lost');});
function guestFixture(phase,registration='closed'){resetTest();state.role='visitor';state.detailStateVersion=1;state.phase=phase;state.registration=registration;location.hash='#season?code=S01';}
test('guest upcoming states retain common content but never show live results',()=>{for(const registration of ['notOpen','open','closed']){guestFixture('upcoming',registration);state.application={name:'私密报名姓名',status:'已通过'};const html=seasonPage();for(const label of ['报名开放','报名截止','开赛','组队截止','命题冻结','作品截止','评分截止','结算','公告','参赛人数','企业命题','赛季规则','评委公示','命题库'])assert(html.includes(label),'Missing guest content '+label);for(const label of ['Top 5','最近动态','战果','已有项目与作品记录','私密报名姓名','报名审核','园区算力拼车'])assert(!html.includes(label),'Upcoming guest contains '+label);assert(html.includes(registration==='open'?'报名中':'即将开始'),'Poster state incorrect');assert(html.includes(registration==='notOpen'?'报名 11月15日 开放':registration==='open'?'立即报名':'浏览命题'),'Guest CTA incorrect');}});
test('guest active registration window is independent and Top 5 uses project totals',()=>{guestFixture('active','open');state.activityProjects=Array.from({length:7},(_,i)=>({id:'gp'+i,name:'公开项目'+i,challenges:['c1'],members:['Test'],stage:'原型',base:7-i}));state.works=[];state.ledger=[];let html=seasonPage();assert(html.includes('进行中')&&html.includes('guest-register:S01'),'Active open registration ignored');assert(html.includes('距作品截止')&&html.includes('参赛人数')&&html.includes('参赛项目')&&html.includes('公开作品')&&html.includes('最近动态')&&html.includes('项目成果'),'Active guest sections missing');assert(html.includes('公开项目4')&&!html.includes('公开项目5'),'Top 5 limit incorrect');state.registration='closed';html=seasonPage();assert(html.includes('浏览项目与作品')&&!html.includes('guest-register:S01'),'Closed active CTA incorrect');});
test('guest settlement and final phases use confirmation and final content',()=>{guestFixture('settling');let html=seasonPage();assert(html.includes('结算进度')&&html.includes('复核中')&&html.includes('复核与结算动态')&&html.includes('预计定格')&&html.includes('公开作品'),'Settling content missing');assert(!html.includes('今日评分')&&!html.includes('>最近动态<')&&!html.includes('guest-register:'),'Settling appears active');for(const phase of ['ended','archived']){state.phase=phase;html=seasonPage();assert(html.includes('查看赛后结果')&&html.includes('最终积分')&&html.includes('奖励发放')&&html.includes('赛后成果'),'Final content missing');assert(!html.includes('最近动态')&&!html.includes('今日评分')&&!html.includes('距作品截止')&&!html.includes('距评分截止'),'Final still live');}});
test('guest suspended and cancelled overlays retain public content without entry actions',()=>{guestFixture('suspended','open');state.previousPhase='active';state.pauseReason='场地调整';let html=seasonPage();assert(html.includes('场地调整')&&html.includes('公告')&&html.includes('赛季规则')&&html.includes('Top 5'),'Pause drops content');assert(!html.includes('guest-register:')&&!html.includes(':apply'),'Paused activity accepts registration');state.phase='cancelled';state.cancelledFromPhase='active';state.cancelReason='活动组织计划取消';html=seasonPage();assert(html.includes('活动组织计划取消')&&html.includes('积分保留为档案，不发奖')&&html.includes('完整赛程时间轴'),'Cancellation details missing');assert(!html.includes('预计奖金')&&!html.includes('Top 5')&&!html.includes('guest-register:')&&!html.includes(':apply'),'Cancellation still offers participation or rewards');});
test('guest cannot see drafts or pending approval even by direct season link',()=>{guestFixture('upcoming','open');for(const draft of [true,false]){state.season.draft=draft;state.season.approved=false;const html=seasonPage();assert(html.includes('尚未公开')&&!html.includes('season-state-hero')&&!html.includes(state.season.theme),'Private season leaked');assert(!featuredEvents().some(e=>e.code==='S01'),'Private event listed');}});
test('guest public outcomes and feed exclude private material',()=>{guestFixture('active');state.works[0].visibility='verification';state.works[0].title='私密作品测试';state.results=[{id:'secret',projectId:'p1',visibility:'verification',status:'已核验',level:'R5',title:'私密收入测试'},{id:'visible',projectId:'p2',visibility:'public',status:'已核验',level:'R5',title:'公开交付测试'}];state.logs=[{action:'报名审核',detail:'私密姓名联系方式',date:'2026-11-10'}];const html=seasonPage();assert(!html.includes('私密作品测试')&&!html.includes('私密收入测试')&&!html.includes('私密姓名联系方式'),'Private material leaked');assert(html.includes('公开交付测试'),'Public verified result missing');assert(guestOutcomes().filter(o=>o.level==='R5').length===1,'R5 includes private evidence');});
test('guest registration prompts login and cannot directly submit',()=>{guestFixture('upcoming','open');assert(!applyPage().includes('data-form="apply"'),'Guest bypasses login');assert(submitTest('apply',{name:'Test',wechat:'demo',skills:'test',direction:'test',time:'test'}),'Visitor directly registered');handleClick({target:{closest:()=>({dataset:{action:'guest-register:W01'}})}});assert(state.role==='visitor'&&elements.get('#modal').innerHTML.includes('登录并继续'),'Missing login step');handleClick({target:{closest:()=>({dataset:{action:'guest-login-continue:W01'}})}});assert(state.role==='participant'&&state.season.code==='W01'&&location.hash==='apply','Login continuation loses activity');});
test('guest archived demo fixtures include complete public results and rewards',()=>{guestFixture('active');for(const code of ['A01','P00']){location.hash='#season?code='+code;const record=publicActivityRecord(code),html=seasonPage();assert(record.activityProjects.length===(code==='A01'?32:13),'Project count mismatch');assert(html.includes('奖励发放')&&html.includes(code==='A01'?'¥20,000':'¥8,000'),'Archive budget missing');assert(!html.includes('待公布')&&!html.includes('待公示')&&!html.includes('最近动态'),'Incomplete final fixture');withPublicActivity(code,()=>{assert(guestEventMetrics().projects===record.activityProjects.length,'Stats mismatch');assert(guestPayoutTotals().approved===used(),'Rewards and scores differ');assert(allocated()<=state.season.pool&&used()<=allocated(),'Pool exceeded');for(const judge of state.judges)assert(judgeUsed(judge.id)<=judge.allocated,'Judge allocation exceeded');assert(state.rewardRecords.every(r=>r.amount===projectScore(projectBy(r.projectId))),'Project reward mismatch');assert(guestEventMetrics().challengeCount===3&&selectableChallenges().length===0,'Archived challenge count or selection incorrect');});}});
test('guest preview controls affect the displayed activity rather than another workspace',()=>{guestFixture('upcoming','notOpen');location.hash='#season?code=H02';preview();assert(state.season.code==='H02','Preview edits a different activity');assert(!submitTest('preview',{phase:'settling',registration:'closed',listState:'normal'}),'Preview update failed');assert(seasonPage().includes('结算进度')&&seasonPage().includes('复核中'),'Displayed phase did not update');assert(state.organizerSeasonRecords.S01.phase==='upcoming','Other activity changed');});
test('public rule card derives from configured limits',()=>{resetTest();state.season.teamLimit=2;state.season.challengeLimit=2;state.season.projectLimit=2;state.season.optionalRules=['保留每周行动记录'];const html=rules();assert(html.includes('1—2 人')&&html.includes('1—2 个')&&html.includes('本季 2 个')&&html.includes('保留每周行动记录'),'Rules not derived from configuration');});

test('organizer navigation separates all seasons from current workspace',()=>{resetTest();state.role='organizer';currentRoute='organizer';const html=organizerPage();assert(html.indexOf('全部赛季')<html.indexOf('sidebar-divider')&&html.indexOf('sidebar-divider')<html.indexOf('sidebar-season-label'),'Sidebar order');assert(html.includes('赛程与状态')&&!html.includes('season-examples'),'Old workspace list remains');const list=organizerSeasonsPage();assert(list.includes('灵感发芽季')&&list.includes('冬日连接季'),'Missing season list');});

test('V2.6 pool denominators and zero pools',()=>{guestFixture('active');state.season.pool=1000;state.judges=[{id:'j',allocated:400}];state.ledger=[{workId:'w1',judge:'j',points:120,date:guestToday()}];const m=guestEventMetrics();assert(m.allocationRate==='40.0%'&&m.usageRate==='30.0%','Pool denominator mismatch '+JSON.stringify(m));state.season.pool=0;state.judges=[];const z=guestEventMetrics();assert(z.allocationRate==='—'&&z.usageRate==='—','Zero denominator');});
test('V2.6 public announcements exclude drafts withdrawn and private audiences including bell',()=>{guestFixture('active');state.announcements=[{id:'pub',title:'公开公告',body:'公开正文',target:'全体用户',status:'published'},{id:'draft',title:'草稿机密',status:'draft',target:'全体用户'},{id:'withdrawn',title:'撤回机密',status:'withdrawn',target:'全体用户'},{id:'private',title:'选手机密',target:'参赛选手',status:'published'}];assert(guestPublicAnnouncements().length===1,'Announcement scope');handleClick({target:{closest:()=>({dataset:{action:'notifications'}})}});const modal=elements.get('#modal').innerHTML;assert(modal.includes('公开公告')&&!modal.includes('机密'),'Bell leaks restricted announcements');handleClick({target:{closest:()=>({dataset:{action:'read-notice:private'}})}});assert(!state.announcements.find(n=>n.id==='private').read,'Direct action bypasses scope');});
test('V2.6 cancellation has original schedule and public announcements without results',()=>{guestFixture('cancelled');state.previousPhase='active';const html=seasonPage();assert(html.includes('已取消')&&html.includes('公告')&&html.includes('报名开放'),'Cancellation essentials');for(const text of ['Top 5','最终战果','赛季规则','已分配／总量','最近动态'])assert(!html.includes(text),'Cancelled page includes '+text);});
test('V2.6 R5 metric includes verified R6 and excludes unverified claims',()=>{guestFixture('active');state.activityProjects=[{id:'r6',r:'R6',rVerified:true},{id:'claim',r:'R5'},{id:'r4',r:'R4',rVerified:true}];state.results=[];assert(guestEventMetrics().r5===1,'Verified R5+ count incorrect');});
test('V2.6 work cutoff retains ongoing phase and both deadlines',()=>{guestFixture('workClosed');const html=seasonPage();assert(html.includes('进行中')&&html.includes('作品提交已截止')&&html.includes('评分截止'),'Work cutoff phase or deadline missing');});
test('V2.6 scoring disabled removes financial metrics and leaderboards',()=>{guestFixture('active');state.season.scoringEnabled=false;const html=seasonPage();for(const label of ['Top 5','已分配／总量','已用／已分配','今日评分'])assert(!html.includes(label),'Non-scoring contains '+label);assert(html.includes('赛季规则')&&html.includes('不计分'),'Non-scoring rules missing');});
test('season listing carousel updates URL and links without embedding detail',()=>{guestFixture('upcoming');selectFeaturedEvent('H02');assert(location.hash.includes('code=H02'),'Carousel URL stale');const html=seasonsPage();assert(html.includes('城市黑客松')&&html.includes('href="#season?code=H02"'),'Carousel target stale');assert(!html.includes('guest-home-context')&&!html.includes('Top 5')&&!html.includes('最近动态')&&!html.includes('完整赛程时间轴'),'Season detail embedded in listing');state.role='participant';assert(!seasonsPage().includes('真实需求，是生长的起点'),'Extra content remains after activity cards');assert(publicActivityRecord('W01').season.type==='season','Workshop treated as third season type');});
test('V2.6 final payout summary uses per-project paid records',()=>{guestFixture('ended');state.rewardRecords=[{projectId:'p1',status:'paid',amount:100},{projectId:'p2',status:'paying',amount:300}];const totals=guestPayoutTotals();assert(totals.approved===400&&totals.paid===100,'Payout progress incorrect');assert(guestTopProjects(true,true).includes('最终项目记录'),'Final public record missing');});


test('unopened growth season has no inherited participation or scored work',()=>{resetTest();state.detailStateVersion=1;state.phase='upcoming';state.registration='notOpen';const record=publicActivityRecord('S01');assert(record.applications.length===0&&record.activityProjects.length===0&&record.works.length===0&&record.ledger.length===0,'Legacy demo participation remains');assert(record.managedChallenges.every(c=>c.taken===0),'Inherited challenge capacity remains');withPublicActivity('S01',()=>{const m=guestEventMetrics();assert(m.approved===0&&m.projects===0&&m.works===0,'Growth season metrics incorrect');});const card=homeEventTickets().find(c=>c.code==='S01');assert(card.seasonStatus==='即将开始'&&!card.showParticipation&&!card.canRegister,'Unopened card has participant content');});
test('cards derive status and registration button from each activity record',()=>{resetTest();const cards=homeEventTickets(),workshop=cards.find(c=>c.code==='W01');assert(workshop.seasonStatus==='报名中'&&workshop.canRegister,'Workshop state mismatch');let html=eventTicketGrid();assert((html.match(/class="event-ticket-button"/g)||[]).length===1&&html.includes('register-public-activity:W01'),'Unexpected card actions');assert(!html.includes('>查看详情<')&&!html.includes('>查看进展<'),'View buttons remain');assert(!html.includes('<a class="event-ticket-link" href="#season?code=W01"><button'),'Button nested in full-card link');enterPublicActivity('W01');state.registration='closed';assert(!homeEventTickets().find(c=>c.code==='W01').canRegister,'Button not driven by registration property');assert(!eventTicketGrid().includes('register-public-activity:W01'),'Closed registration still actionable');});
test('card registration opens login without navigating through detail',()=>{guestFixture('upcoming','notOpen');handleClick({preventDefault(){},target:{closest:()=>({dataset:{action:'register-public-activity:W01'}})}});assert(elements.get('#modal').innerHTML.includes('登录并继续'),'Card registration did not reach login');assert(state.season.code==='S01','Registration click switched activity prematurely');});


test('visitor dashboard shows only public activity statistics',()=>{guestFixture('active');const html=guestStats();for(const label of ['参赛人数','参赛项目','公开作品','奖励池'])assert(html.includes(label),'Public metric missing');for(const label of ['R5','今日评分','评分总次数','已分配','已用','积分池'])assert(!html.includes(label),'Internal metric exposed');state.works[0].visibility='verification';assert(guestStats().includes('公开作品'),'Public work count missing');state.phase='ended';const final=guestFinalSummary();assert(final.includes('已核定奖励')&&final.includes('已发放奖励')&&!final.includes('积分'),'Public reward summary incorrect');});
test('visitor has login instead of personal workspace and following requires login',()=>{guestFixture('upcoming','notOpen');currentRoute='season';renderHeader();let html=elements.get('#header').innerHTML;assert(html.includes('guest-sign-in')&&!html.includes('我的访客工作台')&&!html.includes('class="icon-btn avatar"'),'Guest has personal account UI');state.followed=false;handleClick({target:{closest:()=>({dataset:{action:'follow-public-activity:S01'}})}});assert(state.role==='visitor'&&!state.followed&&elements.get('#modal').innerHTML.includes('登录后关注'),'Anonymous following bypasses login');handleClick({target:{closest:()=>({dataset:{action:'guest-account-continue:S01:follow'}})}});assert(state.role==='participant'&&state.followed,'Follow continuation lost');renderHeader();assert(elements.get('#header').innerHTML.includes('我的参赛者工作台'),'Account workspace missing after prototype login');});


test('timeline uses proportional time fill without a today date label',()=>{guestFixture('active');const midpoint=new Date('2026-11-11T12:00:00+08:00').getTime();assert(seasonTimelineSegmentProgress('2026-11-10','2026-11-12',midpoint)===75,'Timeline fraction incorrect');assert(seasonTimelineSegmentProgress('2026-11-12','2026-11-14',midpoint)===0,'Future segment filled');assert(seasonTimelineSegmentProgress('2026-11-10','2026-11-10',midpoint)===100,'Same-day segment invalid');const html=guestTimeline();assert(!html.includes('今天')&&!html.includes('guest-today-position')&&html.includes('--segment-progress:'),'Today label or non-proportional timeline remains');state.phase='archived';assert((seasonDetailTimeline().match(/--segment-progress:100.00%/g)||[]).length===8,'Final timeline not complete');});


test('public score feed identifies the project and scored work with a matching detail link',()=>{guestFixture('active');enterPublicActivity('H02');state.role='visitor';let html=guestFeed();assert(html.includes('「邻里共享站」的《共享站第一版原型与社区访谈》：评委 林舟 赋分 +120'),'Score attribution missing');assert(html.includes('work?id=hw1'),'Score detail link missing');state.works[0].visibility='verification';html=guestFeed();assert(!html.includes('赋分 +120')&&!html.includes('共享站第一版原型与社区访谈'),'Private score context exposed');});


test('all guest season stages place the timeline directly after statistics',()=>{for(const phase of ['upcoming','active','workClosed','settling','ended','archived','suspended']){guestFixture(phase);if(phase==='suspended')state.previousPhase='active';const html=guestPhaseContent(),stats=html.indexOf('guest-stat-grid'),timeline=html.indexOf('guest-timeline');assert(stats>=0&&timeline>stats,'Stats and timeline order incorrect: '+phase);assert(html.slice(stats,timeline).includes('</div><section class="panel '),'Timeline not directly after stats: '+phase);for(const marker of ['id="guest-live"','>最近动态<','>奖励发放<','>结算进度<']){const position=html.indexOf(marker);assert(position<0||position>timeline,'Stage section precedes timeline: '+phase);}assert((html.match(/aria-label="完整赛程时间轴"/g)||[]).length===1,'Timeline duplicated');}});

test('public UI matches guest components for every signed-in role',()=>{guestFixture('active');const phaseContent=guestPhaseContent(),library=challengesPage(),archive=archivePage(),home=seasonsPage(),card=projectCard(allProjects()[0]);for(const role of ['participant','organizer','judge','enterprise','admin']){state.role=role;assert(guestPhaseContent()===phaseContent,'Public sections differ for '+role);assert(challengesPage()===library,'Library differs for '+role);assert(archivePage()===archive,'Archive differs for '+role);assert(seasonsPage()===home,'Home differs for '+role);assert(projectCard(allProjects()[0])===card,'Project card differs for '+role);assert(challengeCard(publicChallenges()[0])===guestChallengeCard(publicChallenges()[0],{showTarget:true}),'Challenge card differs');}});
test('shared hero retains role entries and registration continuation',()=>{guestFixture('upcoming','open');for(const [role,route] of [['participant','apply'],['organizer','organizer'],['judge','judge'],['enterprise','enterprise'],['admin','admin']]){state.role=role;const html=seasonPage();assert(html.includes('enter-public-activity:S01:'+route),'Role entry missing '+role);assert(!html.includes('guest-register:'),'Signed-in user sent through login');}state.role='participant';state.application={id:'a',status:'已通过'};state.ownProject={id:'mine',name:'我的项目',members:['Test'],challenges:['c1']};let html=seasonPage();assert(html.includes('我的下一步')&&html.includes('进入项目')&&!html.includes('>立即报名<'),'Personal status lost');state.phase='active';html=seasonPage();assert(html.includes('发布赛季作品')&&html.includes('查看下一里程碑'),'Personal actions lost');});
test('all roles use the same final results and retain cross-activity challenge links',()=>{guestFixture('ended');const html=rankingsPage();for(const role of ['participant','organizer','judge','enterprise','admin']){state.role=role;assert(rankingsPage()===html,'Final results differ for '+role);location.hash='#challenges?season=H02';const library=challengesPage();assert(library.includes('enter-public-activity:H02:challenge?id=hc1')&&!library.includes('enter-public-activity:S01:challenge?id=c1'),'Library activity filter or link incorrect');}const before=JSON.stringify(state);location.hash='#season?code=H02';seasonPage();assert(JSON.stringify(state)===before,'Shared browsing changes workspace');});


test('participant demo produces traceable multi-review totals and convertible rewards',()=>{resetTest();loadParticipantDemo('active');assert(state.role==='participant'&&state.application.status==='已通过','Demo qualification');assert(projectScore(state.ownProject)===380,'Project total');assert(participantReward().amount===570,'Conversion not applied');const w=state.works.find(w=>w.id===state.season.code+'-my-work-0');assert(workScore(w)===200&&state.ledger.filter(l=>l.workId===w.id).length===2,'Multi-review fixture incorrect');assert(used()<=allocated(),'Pool overspent');const before=JSON.stringify(state);participantWorkspacePage();participantSeasonBody();assert(JSON.stringify(state)===before,'Rendering mutates scenario');});
test('participant demo lifecycle preserves records and changes write availability',()=>{for(const phase of ['active','workClosed','settling','ended','archived','suspended','cancelled']){resetTest();loadParticipantDemo(phase);const html=PAGES.workspace();assert(html.includes('创作者合作手账')&&html.includes('我的作品与评分'),'Lost personal records: '+phase);assert(Boolean(canWrite('work'))===(phase!=='active'),'Incorrect write availability: '+phase);assert(participantNext().route!=='new-work'||phase==='active','Publish entry after cutoff');if(phase==='cancelled')assert(participantReward().amount===0,'Cancelled reward payable');if(['ended','archived'].includes(phase))assert(state.ledger.every(l=>l.reviewed)&&!state.results.some(r=>r.status==='待核验'),'Incomplete final fixture');} });
test('participant pre-project scenarios keep correct qualification and no project',()=>{for(const scenario of ['pending','waitlist','ready','team']){resetTest();loadParticipantDemo(scenario);assert(!state.ownProject,'Premature project: '+scenario);assert(Boolean(canWrite('project'))===(scenario!=='team'),'Creation qualification: '+scenario);assert(PAGES.workspace().includes('我的参赛进度'),'Missing progress');} });
test('participant private mock work stays out of guest season feed',()=>{resetTest();loadParticipantDemo('active');const privateWork=state.works.find(w=>w.projectId===state.ownProject.id&&w.visibility==='members');state.role='visitor';assert(!guestFeed().includes(privateWork.title),'Private mock work exposed');assert(!guestSeasonBody().includes('MY SEASON'),'Personal dashboard visible to guest');});
test('participant demos keep other season records and cross-page activity context',()=>{resetTest();state.organizerSeasonRecords={OTHER:{season:{code:'OTHER',name:'Other'}}};loadParticipantDemo('active');const other=JSON.stringify(state.organizerSeasonRecords.OTHER),code=state.season.code;enterPublicActivity(code);assert(state.ownProject&&state.works.some(w=>w.projectId===state.ownProject.id),'Navigation lost personal scenario');assert(JSON.stringify(state.organizerSeasonRecords.OTHER)===other,'Other season mutated');const first=projectScore(state.ownProject);loadParticipantDemo('active');assert(projectScore(state.ownProject)===first,'Reload accumulates mock points');});


test('hackathon participant demo keeps its own running schedule and challenge context',()=>{resetTest();enterPublicActivity('H02');loadParticipantDemo('active');assert(state.phase==='active'&&state.registration==='closed','Not active');assert(state.season.dates.join()===HACKATHON_EVENT.dates.join(),'Inherited growth season dates');assert(state.ownProject.name==='邻里共享行动'&&state.ownProject.challenges.join()==='hc1','Wrong project topic');assert(state.works.filter(w=>w.projectId===state.ownProject.id).every(w=>w.date>='2026-11-09'&&w.date<='2026-11-11'&&(!w.tag||w.tag==='hc1')),'Wrong dates or work topics');assert(!state.works.some(w=>['w1','w2','w3'].includes(w.id)),'Growth season background leaked');const html=PAGES.workspace();assert(html.includes('发布赛季作品')&&html.includes('2026-11-11')&&!html.includes('2027-02-20'),'Wrong running workspace');});
test('legacy hackathon demo is repaired without losing scores or other seasons',()=>{resetTest();enterPublicActivity('H02');loadParticipantDemo('active');state.participantDemoVersion=undefined;state.season.dates=INITIAL.season.dates.slice();state.ownProject.name='创作者合作手账';const score=projectScore(state.ownProject);const repaired=publicActivityScenario(state,'H02');assert(repaired.participantDemoVersion===2&&repaired.phase==='active','Legacy repair phase');assert(repaired.season.dates.join()===HACKATHON_EVENT.dates.join(),'Legacy dates not repaired');state=repaired;assert(projectScore(state.ownProject)===score,'Scores lost');const snapshot=JSON.stringify(state);assert(JSON.stringify(repairHackathonParticipantDemo(state))===snapshot,'Migration not idempotent');});
test('unregistered workspace invites season discovery rather than direct registration',()=>{resetTest();state.role='participant';state.application=null;const n=participantNext(),html=PAGES.workspace();assert(n.label==='了解赛季'&&n.route==='seasons','Wrong discovery destination');assert(html.includes('enter-public-activity:S01:seasons')&&!html.includes('>查看报名<'),'Direct registration remains');});

JSON.stringify(results);
'''

context = lib.JSGlobalContextCreate(None)
source = PRELUDE + '\n' + '\n'.join((ROOT / name).read_text() for name in ['data.js', 'app.js', 'views.js', 'guest-seasons.js', 'participant.js', 'interactions.js']) + '\n' + TESTS
script = lib.JSStringCreateWithUTF8CString(source.encode('utf-8'))
exception = PTR()
value = lib.JSEvaluateScript(context, script, None, None, 1, ctypes.byref(exception))

def as_text(value):
    s = lib.JSValueToStringCopy(context, value, None)
    size = lib.JSStringGetMaximumUTF8CStringSize(s)
    buf = ctypes.create_string_buffer(size)
    lib.JSStringGetUTF8CString(s, buf, size)
    return buf.value.decode('utf-8')

if exception.value:
    raise SystemExit('JavaScript error: ' + as_text(exception))
results = json.loads(as_text(value))
for result in results:
    print(('PASS' if result['ok'] else 'FAIL'), result['name'], result.get('error', ''))
for file in ['index.html','styles.css','data.js','app.js','views.js','guest-seasons.js','interactions.js','serve.py']:
    assert (ROOT / file).stat().st_size > 0, file
for file in ['hero.png','switcher.png','ticket.svg','arrow.svg','calendar.svg','users.svg','previous.svg','next.svg']:
    assert (ROOT / 'assets' / file).stat().st_size > 100, file
for file in ['banner.png','enrolled-banner.png','ticket-disabled.svg','ticket-open.svg','ticket-arrow.svg','seal-outer.svg','seal-inner.svg','calendar.svg','users.svg']:
    assert (ROOT / 'assets' / 'season-details' / file).stat().st_size > 100, file
assert len(json.loads((ROOT / 'docs/ia.json').read_text())) == 40
assert not re.search(r'https://www\.figma\.com/api/mcp/asset/', '\n'.join((ROOT/f).read_text() for f in ['index.html','styles.css','data.js','app.js','views.js','guest-seasons.js','interactions.js']))
failures = [r for r in results if not r['ok']]
print('%s/%s JavaScript checks passed; local assets and IA snapshot verified.' % (len(results)-len(failures), len(results)))
raise SystemExit(bool(failures))
